import datetime
import time
from robot.api import logger
from six.moves import input
from tzlocal import get_localzone

from taf.internal.robot_typecasts import time_to_seconds
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_result, log_step, log_iteration
from taf.rfrl.procedures.resources.python.exceptions import ExceededAllowedTimeRange


@log_input_and_output
def wait_until_next_quarter(return_with_timezone=False):
    """
    Waits until the next quarter of an hour.
    :param return_with_timezone: if True, returns datetime object with timezone included
    :type return_with_timezone: bool
    :return: Date of the next quarter.
    :rtype: datetime.datetime object
    """
    now = datetime.datetime.now()
    log_step("Starting awaiting till next quarter, it is {0} right now.".format(now))

    quarters = [0, 15, 30, 45]

    while now.minute not in quarters:
        log_iteration("Waiting next 20 secs till quarter...")
        time.sleep(20)

        now = datetime.datetime.now()
        log_step("It is {0} right now.".format(now))

    log_result("Waiting completed!")
    if return_with_timezone:
        return now.astimezone(get_localzone())
    return now


@log_input_and_output
def wait_full_quarter_cycles(cycles, return_with_timezone=False):
    """
    Waits `cycles` full quarter cycles. That means one full cycle is counted as 15min.
    :param cycles: number of full quarter cycles counted starting from the nearest quarter, e.g. there's 11:10, and it's
                   5 minutes before quarter 11:15, so for 3 cycles starting counting at quarter 15 the ending quarter
                   will be 12:00
    :type cycles: Union[int, str]
    :param return_with_timezone: if True, returns datetime object with timezone included
    :type return_with_timezone: bool
    :return: Date of the last quarter.
    :rtype: datetime.datetime object
    """
    cycles = int(cycles)
    now = datetime.datetime.now()
    log_step(f"Starting awaiting {cycles} quarter cycles, it is {now} right now.")

    quarters = [15, 30, 45, 60]
    quarter_suffix = ['st', 'nd', 'rd', 'th']

    for _ in range(cycles):
        next_full_quarter = min(filter(lambda delta: delta >= 15, map(lambda quarter: quarter - now.minute, quarters)),
                                default=15 - now.minute) + now.minute
        quarter_index = quarters.index(next_full_quarter)
        next_full_quarter = next_full_quarter if next_full_quarter != 60 else 0

        log_step(f"Waiting for {quarter_index+1}{quarter_suffix[quarter_index]} quarter")
        while now.minute != next_full_quarter:
            now = datetime.datetime.now()

        log_step("It is {0} right now.".format(now))

    log_result("Waiting completed!")
    if return_with_timezone:
        return now.astimezone(get_localzone())
    return now


@log_input_and_output
def wait_until_minutes_before_next_quarter(minutes):
    """
    Waits until there are `minutes` minutes before next quarter. If provided minutes exceeds possible value for the next
    quarter, then function will wait for another one, e.g. it's 11:12 and user provided 5 min, that means that the next
    possible time is 11:25.
    :param minutes: minutes to which user wants to wait before next quarter, range [1-14]min
    :type minutes: Union[int, str]
    :raises ExceededAllowedTimeRange: if provided minutes exceeds [1-14]min range
    """
    minutes = int(minutes)

    if not 14 >= minutes >= 1:
        raise ExceededAllowedTimeRange("Provided minutes before next quarter must be in range [1-14] min")

    now = datetime.datetime.now()
    quarters = [15, 30, 45, 60]

    next_quarter = min(filter(lambda delta: delta >= minutes, map(lambda quarter: quarter - now.minute, quarters)),
                       default=15 - now.minute) + now.minute
    quarter_index = quarters.index(next_quarter)
    quarter_suffix = ['st', 'nd', 'rd', 'th']

    log_step(f"Starting awaiting {minutes} minutes before {quarter_index+1}{quarter_suffix[quarter_index]} quarter")
    while now.minute != next_quarter - minutes:
        now = datetime.datetime.now()

    log_result("Waiting completed!")


@log_input_and_output
def wait_until_next_hour():
    """
    Waits until the next hour.
    :return: Date of the next quarter.
    :rtype: datetime.datetime object
    """
    now = datetime.datetime.now()
    log_step("Starting awaiting till next hour, it is {0} right now.".format(now))
    next_hour = now.hour + 1 if now.hour < 23 else 0

    while now.hour != next_hour:
        time.sleep(30)

        now = datetime.datetime.now()
        log_step("It is {0} right now.".format(now))

    log_result("Waiting completed!")
    return now


def wait_until_specific_time_passed(start, time):
    """
    Checks if time duration provided by user passed from `start` date - if not, then
    keyword waits until specific date time, e.g.

    start: 15:07:40
    time: 30seconds
    now: 15:07:55

    then method will wait till 15:08:10 (15 seconds sleep).

    :param start: Start date that user wants to count time period from.
    :type start: datetime.datetime object
    :param time: Awaiting time.
    :type time: str, accepts Robot string time format i.e. 1 min 30 sec
    """
    now = datetime.datetime.now()
    log_step("The time is {0} \n"
             "Start time passed to method: {1} \n".format(now, start))

    wait_till = _get_target_date_to_wait_for(start, time)
    log_result("Target awaiting time: {0}".format(wait_till))

    if now < wait_till:
        _sleep_for_remaining_time(wait_till, now)

    log_result("Desired date passed, let's go further!")


@log_input_and_output
def pause_execution_till_enter(message):
    """
    Pause test execution until user presses Enter.

    :param message: message for the user, e.g. manually step
    :type message: str
    """
    logger.console('\n\n' + message)
    input()


@log_input_and_output
def _get_target_date_to_wait_for(start, wait_time):
    delta = datetime.timedelta(seconds=time_to_seconds(wait_time))
    if isinstance(start, str):
        start = datetime.datetime.strptime(start, "%Y-%m-%d %H:%M:%S.%f")
    return start + delta


@log_input_and_output
def _sleep_for_remaining_time(target, now):
    remaining_time = target - now
    log_step("To get {0}, {1} seconds sleep has been set".format(target, remaining_time))
    time.sleep(remaining_time.total_seconds())
